import SwiftUI
import UIKit

enum AppLogoProvider {
    static let base64String: String = ""

    static let uiImage: UIImage? = {
        if let bundled = UIImage(named: "AppLogo.jpg") ?? UIImage(named: "AppLogo") {
            return bundled
        }
        guard let data = Data(base64Encoded: base64String) else { return nil }
        return UIImage(data: data)
    }()
}
